CREATE POLICY "kids-drawings upload own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'kids-drawings' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "kids-drawings read public" ON storage.objects FOR SELECT USING (bucket_id = 'kids-drawings');
CREATE POLICY "kids-drawings update own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'kids-drawings' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "kids-drawings delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'kids-drawings' AND (storage.foldername(name))[1] = auth.uid()::text);